// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/auth/code", wrapper.RequestEmailCode)
	router.POST(options.BaseURL+"/auth/email/check", wrapper.CheckEmail)
	router.POST(options.BaseURL+"/auth/login", wrapper.Login)
	router.POST(options.BaseURL+"/auth/logout", wrapper.Logout)
	router.GET(options.BaseURL+"/auth/me", wrapper.GetMe)
	router.POST(options.BaseURL+"/auth/password/reset", wrapper.ResetPassword)
	router.POST(options.BaseURL+"/auth/register", wrapper.Register)
	router.GET(options.BaseURL+"/health", wrapper.GetHealth)
	router.GET(options.BaseURL+"/levels/sets", wrapper.ListLevelSets)
	router.DELETE(options.BaseURL+"/me/avatar", wrapper.DeleteMyAvatar)
	router.GET(options.BaseURL+"/me/avatar", wrapper.GetMyAvatar)
	router.POST(options.BaseURL+"/me/avatar", wrapper.PutMyAvatar)
	router.GET(options.BaseURL+"/me/collections", wrapper.ListCollections)
	router.POST(options.BaseURL+"/me/collections", wrapper.CreateCollection)
	router.DELETE(options.BaseURL+"/me/collections/:id", wrapper.DeleteCollection)
	router.PATCH(options.BaseURL+"/me/collections/:id", wrapper.RenameCollection)
	router.DELETE(options.BaseURL+"/me/collections/:id/levels/:levelId", wrapper.RemoveCollectionItem)
	router.PUT(options.BaseURL+"/me/collections/:id/levels/:levelId", wrapper.AddCollectionItem)
	router.GET(options.BaseURL+"/me/daily", wrapper.ListDailyHistory)
	router.GET(options.BaseURL+"/me/levels", wrapper.ListLevelProgress)
	router.POST(options.BaseURL+"/me/levels/:id", wrapper.RecordLevelResult)
	router.GET(options.BaseURL+"/me/mistakes", wrapper.ListMistakes)
	router.DELETE(options.BaseURL+"/me/mistakes/:id", wrapper.ResolveMistake)
	router.PUT(options.BaseURL+"/me/name", wrapper.SetMyName)
	router.PUT(options.BaseURL+"/me/password", wrapper.SetMyPassword)
	router.GET(options.BaseURL+"/me/plan", wrapper.GetStudyPlan)
	router.PUT(options.BaseURL+"/me/plan", wrapper.UpdateStudyPlan)
	router.POST(options.BaseURL+"/me/practice-records", wrapper.CreatePracticeRecord)
	router.GET(options.BaseURL+"/me/stats", wrapper.GetPracticeStats)
}

